export const testimonials = [
  {name:'Azizbek Karimov', role:{uz:'Retail kompaniya direktori',ru:'Директор retail-компании'}, text:{uz:'Hisobotlarimiz tartibga tushdi, soliq bo‘yicha xavotirlar ancha kamaydi.', ru:'Отчётность стала системной, налоговые риски заметно снизились.'}},
  {name:'Madina Sobirova', role:{uz:'Servis markazi asoschisi',ru:'Основатель сервисного центра'}, text:{uz:'Jamoa tezkor, aniq va juda mas’uliyatli ishlaydi. Tavsiya qilaman.', ru:'Команда работает быстро, точно и ответственно. Рекомендую.'}},
  {name:'Dmitriy Orlov', role:{uz:'Logistika kompaniyasi moliya rahbari',ru:'Финансовый руководитель логистической компании'}, text:{uz:'Outsourcing modeli bizga xarajat va vaqtni tejashga yordam berdi.', ru:'Аутсорсинг помог нам сэкономить время и расходы.'}},
  {name:'Nilufar Tursunova', role:{uz:'Ishlab chiqarish korxonasi boshqaruvchisi',ru:'Управляющая производственной компании'}, text:{uz:'Hujjatlar, ish haqi va hisobotlar bir tizimga keldi.', ru:'Документы, зарплата и отчёты стали единым управляемым процессом.'}}
];
